def _kernels(routes,n):
    def norm(w): return (w-w[:n].mean(0))/np.maximum(w[:n].std(0),1e-7)
    def dot(w): return w@w[:n].T/w.shape[1]
    R=[norm(w) for w in routes]; a,x,c,d,b,b2,p=R; sets=[a,x,b,b2,d,np.c_[x,b],np.c_[x,b,b2,c,d,p]]; K=[]
    for w in R:
